import {shiftDate} from './age.js';
import {calcField as field,calcSelect as select,calcCheck as check,calcDisclosure as details,calcEscape as esc} from './calculator-view.js';
import {normalizeFormalDetails,FORMAL_SOURCES,FORMAL_RULES,DEADLINE_REGISTRY} from './formal-registry.js';
import {FAMILY_RECORD_STATUSES} from './family-ledger.js';
const tri=[['unknown','Nie wiem / do ustalenia'],['yes','Tak'],['no','Nie']];
function funeralQuestionsHtml(input){
 const p='formalCase.',d=input.formalCase;
 const answer=(key,label)=>select(input,p+key,label,tri);
 const single=answer('singleFuneralPayer','Czy tylko jedna osoba lub jeden podmiot poniósł koszty pogrzebu?');
 const costs=d.singleFuneralPayer==='no'?d.funeralPayers.map((person,i)=>`<fieldset class="formal-child"><legend>Osoba / podmiot ${i+1}</legend>${select(input,p+'funeralPayers.'+i+'.relation','Relacja ze zmarłym',[['unknown','Nie wiem / do ustalenia'],['family','Członek rodziny'],['other','Osoba lub podmiot spoza rodziny']])}${field(input,p+'funeralPayers.'+i+'.cost','Poniesione koszty (zł)',{step:.01})}</fieldset>`).join('')+'<button class="secondary" type="button" id="formal-add-funeral-payer">Dodaj osobę lub podmiot ponoszący koszty</button>'+select(input,p+'claimantPayerId','Czyj udział w świadczeniu sprawdzamy?',[['','Wybierz osobę'],...d.funeralPayers.map((r,i)=>[r.id,'Osoba / podmiot '+(i+1)])]):select(input,p+'funeralRelation','Kto poniósł koszty pogrzebu?',[['unknown','Nie wiem / do ustalenia'],['family','Członek rodziny zmarłego'],['other','Osoba lub podmiot spoza rodziny']])+field(input,p+'funeralCosts','Faktycznie poniesione koszty pogrzebu (zł)',{step:.01});
 return `<section class="calc-section formal-questions funeral-questions"><h2>Informacje potrzebne do sprawdzenia świadczenia</h2><div class="calc-fields">${field(input,p+'deathDate','Data śmierci / martwego urodzenia',{type:'date'})}${field(input,p+'funeralDate','Data pogrzebu (jeśli znana)',{type:'date'})}</div>${answer('deathBasis','Czy potwierdzono podstawę prawa wynikającą ze statusu zmarłego lub członka jego rodziny?')}<details class="support-explanation"><summary>Co oznacza podstawa prawa?</summary><p>Znaczenie ma m.in. objęcie zmarłego ubezpieczeniem, pobieranie emerytury lub renty albo jego relacja rodzinna z osobą mającą właściwy status. Same rachunki nie wystarczają do ustalenia wszystkich warunków. Jeśli nie wiesz, wybierz „Nie wiem / do ustalenia” — wynik wskaże, co sprawdzić w ZUS.</p><a href="https://www.zus.pl/pl/swiadczenia/zasilki/zasilek-pogrzebowy" target="_blank" rel="noopener noreferrer">Kto może otrzymać pogrzebowe — ZUS ↗</a></details>${single}${costs}<details class="support-explanation"><summary>Dokumenty i termin wniosku</summary><p>Przygotuj Z-12, dokument zgonu lub właściwy dokument medyczny po martwym urodzeniu, rachunki oraz dokumenty potwierdzające pokrewieństwo i podstawę prawa. Nie trzeba podawać wieku dziecka w tygodniach ani ustalać jego płci dla dopuszczalnego zaświadczenia po stracie ciąży.</p><p>Wniosek składa się zasadniczo w ciągu 12 miesięcy od śmierci. Udokumentowana niezależna przeszkoda może uzasadniać szczególny termin od pogrzebu; sprawdź to z ZUS.</p>${field(input,p+'submissionDate','Data złożenia wniosku (jeśli już złożony)',{type:'date'})}</details></section>`;
}
export function formalQuestionsHtml(input,recordsSnapshot=null){
 input.formalCase=normalizeFormalDetails(input.formalCase);const d=input.formalCase,f=input.focus,p='formalCase.',people=recordsSnapshot?.records?.persons||[],children=recordsSnapshot?.records?.children||[];
 if(d.topic==='funeral')return funeralQuestionsHtml(input);
 const date=(key,label)=>field(input,p+key,label,{type:'date'}),answer=(key,label)=>select(input,p+key,label,tri);
 let body='';
 if(f==='family')body+=select(input,p+'topic','Zdrowie dziecka i szczególne sytuacje',[['none','Nie dotyczy / zwykły plan'],['prematurity','Poród przedwczesny'],['hospital','Hospitalizacja dziecka, także ponowna'],['serious-illness','Poważna choroba dziecka — odrębnie od orzeczenia'],['disability','Orzeczenie o niepełnosprawności'],['life','Zaświadczenie „Za życiem”'],['constant-care','Dziecko wymaga stałej opieki'],['stillbirth','Martwe urodzenie'],['child-death','Śmierć dziecka po żywym urodzeniu'],['parent-death','Śmierć rodzica'],['funeral','Zasiłek pogrzebowy — osobne ustalenie'],['adoption-change','Przejście z pieczy do adopcji'],['other','Inne szczególne okoliczności']]);
 if(f==='family'&&(input.familyType!=='birth'||input.count>1||input.hospitals.length||['prematurity','hospital','adoption-change'].includes(d.topic)))body+=details('Dane każdego dziecka z tego zdarzenia',`<p>Osobne daty i masy. Różne daty przyjęcia nie są jednym wspólnym przyjęciem. Pobyt szpitalny przypisz do numeru dziecka w planie.</p>${d.children.map((c,i)=>`<fieldset class="formal-child"><legend>Dziecko ${i+1}</legend><div class="calc-fields">${field(input,p+'children.'+i+'.birthDate','Data urodzenia',{type:'date'})}${field(input,p+'children.'+i+'.placementDate','Data przyjęcia na wychowanie',{type:'date'})}${field(input,p+'children.'+i+'.weight','Masa urodzeniowa (g), gdy dotyczy',{step:1,min:100,max:10000})}</div><button type="button" class="text-button" data-formal-remove-child="${i}">Usuń ten wpis z formularza</button></fieldset>`).join('')}<button type="button" class="secondary" id="formal-add-child">Dodaj dziecko w tym zdarzeniu</button>${input.hospitals.length?field(input,p+'gestationWeek','Ukończony tydzień ciąży przy porodzie z dokumentacji',{step:1,min:20,max:44})+field(input,p+'gestationDay','Dzień w ukończonym tygodniu ciąży przy porodzie (0–6)',{step:1,min:0,max:6,help:'Tydzień podajesz w danych porodu powyżej; dzień odczytaj z dokumentacji.'}):''}`);
 if(f==='family'&&(input.familyType!=='birth'||d.topic==='adoption-change'))body+=answer('priorFoster','Czy dla tego samego dziecka wcześniej korzystano z uprawnień z tytułu pieczy?')+date('adoptionTransitionDate','Data zmiany sytuacji z pieczy na adopcję')+date('schoolDeferralDate','Data decyzji o odroczeniu obowiązku szkolnego');
 if(f==='family'&&(input.loss!=='none'||['stillbirth','child-death','parent-death','funeral'].includes(d.topic)))body+=details('Dokumenty i sytuacja w chwili zdarzenia',select(input,p+'currentLeave','Z jakiego urlopu lub okresu zasiłku korzystano w chwili zdarzenia?',[['unknown','Do ustalenia'],['none','Nie korzystano'],['maternity','Macierzyński'],['parental','Rodzicielski'],['paternity','Ojcowski'],['adoption','Na warunkach macierzyńskiego — adopcja'],['foster','Na warunkach macierzyńskiego — piecza']])+date('deathDate','Data śmierci / martwego urodzenia')+select(input,p+'affectedParent','Jeżeli zmarł rodzic — którego rodzica dotyczy zdarzenie?',[['unknown','Do ustalenia / nie dotyczy'],['mother','Matki'],['father','Ojca'],['other','Innego opiekuna']])+answer('stillbirthAct','Czy sporządzono akt urodzenia z adnotacją o martwym urodzeniu?')+answer('stillbirthCertificate','Czy jest właściwe zaświadczenie lekarza lub położnej, gdy nie ma aktu?')+'<p>Nie wymagamy ustalenia płci dziecka. Zgon rodzica i zgon dziecka mają różne skutki — wybierz właściwą przesłankę przejęcia w planie.</p>',true);
 if(f==='family'&&d.topic==='funeral')body+=details('Pogrzebowe — dane do odrębnej oceny',answer('deathBasis','Czy potwierdzono podstawę prawa: właściwy status zmarłego lub członka jego rodziny?')+select(input,p+'funeralRelation','Kto poniósł koszty?',[['unknown','Do ustalenia'],['family','Członek rodziny'],['other','Osoba / podmiot spoza rodziny']])+field(input,p+'funeralCosts','Poniesione koszty pogrzebu (zł)',{step:.01})+answer('singleFuneralPayer','Czy tylko ta osoba / ten podmiot poniósł koszty?')+date('funeralDate','Data pogrzebu, jeśli istotna dla wyjątku od terminu')+'<p>Przy kilku osobach kosztów nie rozliczamy jako kilku pełnych świadczeń. Podział wymaga ustalenia w ZUS.</p>',true);
 if(f==='family'&&d.topic==='funeral'&&d.singleFuneralPayer==='no')body+=details('Podział kosztów między osoby / podmioty',d.funeralPayers.map((person,i)=>'<fieldset class="formal-child"><legend>Osoba / podmiot '+(i+1)+'</legend>'+select(input,p+'funeralPayers.'+i+'.relation','Relacja ze zmarłym',[['unknown','Do ustalenia'],['family','Członek rodziny'],['other','Osoba / podmiot spoza rodziny']])+field(input,p+'funeralPayers.'+i+'.cost','Koszty poniesione przez tę osobę / podmiot (zł)',{step:.01})+'</fieldset>').join('')+'<button class="secondary" type="button" id="formal-add-funeral-payer">Dodaj osobę / podmiot ponoszący koszty</button>'+select(input,p+'claimantPayerId','Czyj udział obliczamy?',[['','Wybierz osobę'],...d.funeralPayers.map((r,i)=>[r.id,'Osoba / podmiot '+(i+1)])]),true);
 if(f==='care')body+=details('Dokumenty, orzeczenie i rzeczywista możliwość opieki',answer('careCertificate','Czy chorobę / konieczność opieki potwierdzono właściwym dokumentem?')+(input.care.type==='disabled-child'?select(input,p+'careReason','Przy niepełnosprawności — z czego wynika potrzeba opieki?',[['unknown','Do ustalenia'],['sick','Choroba dziecka'],['regular-carer','Dotychczasowy stały opiekun nie może zapewnić opieki']])+answer('disabilityQualified','Czy rodzaj orzeczenia i jego wskazania spełniają warunki tego świadczenia?')+date('disabilityIssued','Data wydania orzeczenia')+date('disabilityFrom','Orzeczenie obejmuje okres od')+date('disabilityTo','Orzeczenie obejmuje okres do, jeśli terminowe')+answer('disabilityIndefinite','Czy orzeczenie jest bezterminowe?'):'')+select(input,p+'otherCarer','Czy inny domownik faktycznie może zapewnić opiekę?',[['unknown','Do ustalenia'],['available','Tak, może zapewnić opiekę'],['unavailable','Nie, rzeczywiście nie może'],['exception','Występuje wyjątek — wymaga sprawdzenia']])+answer('careOtherBenefit','Czy w tym okresie występuje inne świadczenie / urlop mogący wyłączać opiekuńczy?')+(input.care.type==='healthy-child'&&input.care.reason==='closure'?date('closureInformed','Data zawiadomienia o zamknięciu placówki')+date('closureDate','Pierwszy dzień zamknięcia placówki'):'')+answer('niaContract','Przy chorobie niani — czy zatrudniono ją na właściwej umowie?')+'<p>Ciężka choroba, niepełnosprawność i zaświadczenie „Za życiem” to odrębne przesłanki. Opiekuńczy nie jest świadczeniem pielęgnacyjnym.</p>',true);
 if(f==='care'&&(input.care.start||input.eventDate)){const first=input.care.start||input.eventDate,end=shiftDate(first,input.care.days-1);input.care.yearUsage??={};for(let year=Number(first.slice(0,4))+1;year<=Number(end.slice(0,4));year++){input.care.yearUsage[year]??={usedAll:null,usedDisabled:null,usedAdult:null};body+=details('Wykorzystanie opiekuńczego w roku '+year,field(input,'care.yearUsage.'+year+'.usedAll','Dni wykorzystane przez rodzinę w tym roku',{step:1,max:365})+field(input,'care.yearUsage.'+year+'.usedDisabled','W tym podlimit niepełnosprawności',{step:1,max:365})+field(input,'care.yearUsage.'+year+'.usedAdult','W tym podlimit innych chorych członków rodziny',{step:1,max:365})+'<p>Nie kopiujemy dni z poprzedniego roku. Puste pole oznacza brak danych.</p>');}}
 if(['sickness','rehab','prebirth'].includes(f))body+=details('Daty medyczne i zmiany okoliczności',date('previousSicknessStart','Początek wcześniejszego zwolnienia')+date('previousSicknessEnd','Koniec wcześniejszego zwolnienia')+date('pregnancyEnd','Zakończenie ciąży, jeśli następuje wewnątrz badanego okresu')+date('sicknessExhausted','Data wyczerpania okresu zasiłkowego')+date('medicalOpinionDelivered','Data doręczenia orzeczenia lekarza orzecznika')+answer('multipleTitleExemption','Od 2027 r.: czy lekarz nie wystawił e-ZLA z jednego z tytułów na żądanie ubezpieczonego?')+'<p>Przepisy przejściowe i zakres zwolnień z kilku tytułów wymagają odrębnego sprawdzenia. Sprzeciw od orzeczenia nie jest tym samym co odwołanie od decyzji.</p>');
 if(f==='rehab')body+=details('Kontynuacja rehabilitacyjnego',field(input,'sickness.rehabUsedDays','Dni rehabilitacyjnego wykorzystane przed początkiem tej części',{step:1,min:0,max:360})+answer('rehabContinues','Czy decyzja potwierdza dalszy okres rehabilitacyjnego także po zakończeniu ciąży?')+answer('afterPregnancyExclusion','Czy po zakończeniu ciąży występuje macierzyński lub inne uprawnienie wyłączające rehabilitacyjne?')+'<p>Wcześniejsze dni rehabilitacyjnego nie są wcześniejszymi dniami chorobowego. Przy kontynuacji podaj podstawę już zwaloryzowaną dla pierwszego dnia przyznanego świadczenia; nie waloryzujemy jej ponownie.</p>');
 if(f==='family'&&input.transfer!=='none')body+=select(input,p+'transferRecipient','Kto przejmuje uprawnienie?',[['unknown','Do ustalenia'],['father','Ojciec dziecka'],['family','Inny uprawniony członek najbliższej rodziny']])+answer('closestFamilyConfirmed','Czy potwierdzono wymagany status członka najbliższej rodziny?');
 if(f==='family')body+=details('Wyrównanie stawki do 100%',answer('equalizationRequested','Czy chcesz sprawdzić wyrównanie po pierwszym roku?')+answer('noParentalFirstYear','Czy przez pierwszy rok nie wykorzystano ani jednego dnia właściwego rodzicielskiego w wariancie 81,5%?')+answer('actualPaymentConfirmed','Czy posiadasz potwierdzoną historię rzeczywistych wypłat?')+select(input,p+'equalizationParent','Czyje wyrównanie sprawdzamy?',[[0,'Osoba 1'],[1,'Osoba 2']])+field(input,p+'actualMaternityGross','Rzeczywiście pobrane brutto za objęty wyrównaniem macierzyński (zł)',{step:.01})+'<p>Wyrównanie wymaga osobnego wniosku i historii. Nie dodajemy go automatycznie do przyszłego planu.</p>');
 body+=details('Daty prawa, wniosku i decyzji',select(input,p+'contractType','Rodzaj umowy, gdy istotny dla końca zatrudnienia',[['unknown','Do ustalenia / nie dotyczy'],['fixed','Na czas określony'],['permanent','Na czas nieokreślony'],['replacement','Na zastępstwo'],['probation','Na okres próbny'],['other','Inna']])+answer('employmentExtensionConfirmed','Czy pracodawca / dokumenty potwierdzają przedłużenie umowy do dnia porodu?')+date('entitlementDate','Data powstania prawa ustalona w dokumentach — jeśli znana')+date('paymentStart','Data rozpoczęcia wypłaty — jeśli ustalona')+date('submissionDate','Data złożenia wniosku — wybór właściwego formularza')+date('decisionDate','Data wydania decyzji')+date('decisionDelivered','Data doręczenia decyzji')+date('decisionFinal','Data prawomocności / ostateczności, gdy dotyczy')+answer('foreignDocument','Czy dokument pochodzi z zagranicy?')+answer('translationExemption','Jeśli tak — czy ustalono zwolnienie z tłumaczenia w tej procedurze?')+date('employmentStart','Data rozpoczęcia zatrudnienia — odrębnie od zgłoszenia ubezpieczenia')+date('employmentEnd','Data zakończenia zatrudnienia')+date('insuranceReported','Data zgłoszenia do chorobowego')+date('fteChangedAt','Data zmiany etatu')+'<p>Daty nie są zamienne. Pusta data pozostaje nieustalona. Nie oznaczamy jej automatycznie dniem porodu.</p>');
 body+=details('Wspólna historia rodziny',(children.length?select(input,p+'childReference','Dziecko z mojego rejestru',[['','Wybierz dziecko / użyj danych profilu'],...children.map(c=>[c.id,c.name])]):field(input,p+'childReference','Stałe oznaczenie tego samego dziecka przy zmianie pieczy na adopcję',{type:'text',help:'W obu sprawach wpisz to samo oznaczenie; nie podawaj PESEL.'}))+select(input,p+'recordStatus','Stan tego scenariusza',Object.entries(FAMILY_RECORD_STATUSES))+(people.length?select(input,p+'personIds.0','Osoba 1 w moim rejestrze',[['parent-1','Osoba 1 — dotychczasowe oznaczenie'],...people.map(p=>[p.id,p.name])]):field(input,p+'personIds.0','Stałe oznaczenie osoby 1 w rodzinie',{type:'text',help:'Używaj tego samego oznaczenia tej osoby we wszystkich scenariuszach; nie podawaj PESEL.'}))+(people.length?select(input,p+'personIds.1','Osoba 2 w moim rejestrze',[['parent-2','Osoba 2 — dotychczasowe oznaczenie'],...people.map(p=>[p.id,p.name])]):field(input,p+'personIds.1','Stałe oznaczenie osoby 2 w rodzinie',{type:'text'}))+check(input,p+'historyComplete','Podane wykorzystanie obejmuje całą znaną historię rodziny, również poza aplikacją')+'<p>Planowane warianty nie zużywają faktycznie wykorzystanych limitów. Zatwierdzenie zaznaczasz na podstawie własnych dokumentów — aplikacja nie pobiera decyzji z ZUS. Zmiana jednej sprawy wymaga ponownego sprawdzenia powiązanych planów.</p>');
 return `<section class="calc-section formal-questions"><h2>Szczegóły istotne dla tej sprawy</h2><p>Uzupełniaj wyłącznie informacje dotyczące wybranego uprawnienia. Przy braku danych pokażemy, co ustalić i gdzie.</p>${body}</section>`;
}
export function formalResultHtml(result){const d=result.formalDecision;if(!d)return '<div class="calc-notice">To wcześniejszy zapis. Przelicz go, aby sprawdzić historię rodziny i nowe reguły formalne.</div>';return `<section class="formal-decision calc-section" aria-live="polite"><span class="eyebrow">Ocena informacyjna — nie decyzja organu</span><h2 tabindex="-1">${esc(d.label)}</h2>${result.caseChanges?.length?'<section class="calc-notice"><h3>Co zmieniło się po ponownym przeliczeniu?</h3><ul>'+result.caseChanges.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></section>':''}${result.archivedVersions?'<button class="secondary" id="formal-view-history">Zobacz poprzednie wersje tej sprawy</button>':''}${result.comparison?'<details><summary>Porównanie z poprzednim planem</summary>'+result.comparison.differences.map(d=>'<p><strong>'+esc(d.category)+'</strong>: '+esc(d.before??'Do ustalenia')+' → '+esc(d.after??'Do ustalenia')+'</p>').join('')+'</details>':''}${result.equalization?'<section class="case-card"><h3>Wyrównanie do 100% — osobna ocena</h3><p>'+esc(result.equalization.amount==null?result.equalization.missing:'Możliwa kwota brutto z podanych danych: '+result.equalization.amount.toLocaleString('pl-PL')+' zł')+'</p><p>Wypłata wymaga właściwego wniosku i potwierdzenia historii przez płatnika.</p></section>':''}<h3>Dlaczego otrzymuję taki wynik?</h3>${d.issues.length?d.issues.map(i=>`<article class="calc-notice"><p>${esc(i.message)}</p>${i.legalBasis?`<details><summary>Podstawa prawna</summary><p>${esc(i.legalBasis)}</p>${i.url?`<a href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">Oficjalne wyjaśnienie</a>`:''}</details>`:''}</article>`).join(''):result.input.formalCase?.topic==='funeral'?'<p>Uwzględniono podaną datę śmierci, podstawę prawa, relację rodzinną, koszty i liczbę osób, które je poniosły. To jednorazowe świadczenie; data śmierci nie jest datą wypłaty. Dane wymagają potwierdzenia w ZUS.</p>':'<p>Wynik opiera się na podanym tytule, okresach, podstawie i deklarowanych dokumentach. Wyjaśnienia dla każdej osoby są poniżej. Dane nie zostały zatwierdzone przez urząd.</p>'}${d.nextSteps.length?'<h3>Co dalej?</h3><ol>'+d.nextSteps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>':''}${d.documents.length?'<h3>Co przygotować?</h3><ul>'+d.documents.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':''}<details><summary>Właściwe dokumenty i wersje wzorów</summary>${result.documentRegister.map(x=>`<article><h4>${esc(x.code)} — ${esc(x.purpose)}</h4><p>${esc(x.recipient)}. ${esc(x.selectionReason)}: ${esc(x.selectedFor)}.</p><p>${esc(x.registryAcquisition)}</p><ul>${x.attachments.map(a=>'<li>'+esc(a)+'</li>').join('')}</ul><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Oficjalne dokumenty</a></article>`).join('')}</details><details><summary>Dane, wersje reguł i możliwość odtworzenia wyniku</summary><p>Obliczono: ${esc(result.calculatedOn)}. Parametry: ${esc(result.rulesVersion)}. Rejestr: ${esc(d.registryVersion)}. Zatwierdzenie eksperckie przez ZUS: nie wykonano.</p>${result.audit.legalReview?'<p>Weryfikacja redakcyjna: '+esc(result.audit.legalReview.reviewer)+'. Podstawa: '+esc(result.audit.legalReview.legalBasis)+'. Przepisy przejściowe: '+esc(result.audit.legalReview.transitionNote)+'.</p>':''}${result.audit.assumptions.map(a=>'<p>'+esc(a)+'</p>').join('')}<p>Data zdarzenia: ${esc(result.audit.sourceDates.event)}; ustalona data prawa: ${esc(result.audit.sourceDates.entitlement||'nie podano')}; wniosek: ${esc(result.audit.sourceDates.submission||'nie podano')}; wypłata od: ${esc(result.audit.sourceDates.paymentStart||'nie podano')}.</p></details></section>`;}
